-- ============================================================================
-- Custom Sign Studio - Idempotent Seed SQL (Demo Data)
-- Safe to run multiple times: uses ON CONFLICT DO UPDATE / DO NOTHING.
-- All Demo records are marked with `is_demo = true` so they are never confused
-- with real customer orders, real revenue, or real reviews, and can be deleted
-- cleanly at any time (`DELETE FROM ... WHERE is_demo = true`).
-- ============================================================================

-- 1. Category Groups (4 Groups)
insert into public.category_groups (id, slug, name, description, icon_name, sort_order, is_active, is_demo)
values
  ('10000000-0000-0000-0000-000000000001', 'shop-identity', 'ป้ายตัวตนและข้อมูลร้าน', 'ป้ายแนะนำร้าน รายละเอียดร้าน เวลาเปิด-ปิด และกฎกติกาของร้าน', 'Store', 1, true, true),
  ('10000000-0000-0000-0000-000000000002', 'payment-pricing', 'ป้ายการเงินและเรทราคา', 'ป้ายเลขบัญชีธนาคาร ช่องทางชำระเงิน เรทราคา และโปรโมชั่น', 'CreditCard', 2, true, true),
  ('10000000-0000-0000-0000-000000000003', 'trust-social', 'ป้ายรีวิวและเครดิตความน่าเชื่อถือ', 'ป้ายรีวิวลูกค้า ป้ายเครดิต และป้ายขอบคุณลูกค้า', 'Heart', 3, true, true),
  ('10000000-0000-0000-0000-000000000004', 'shipping-contact', 'ป้ายจัดส่งและแจ้งข่าวสาร', 'ป้ายแจ้งเลขพัสดุ ช่องทางติดต่อ ป้ายวันหยุด และป้ายอื่น ๆ', 'Truck', 4, true, true)
on conflict (slug) do update
  set name = excluded.name,
      description = excluded.description,
      sort_order = excluded.sort_order;

-- 2. Sign Categories (15 Sign Types per PART 1 & PART 20)
insert into public.sign_categories (
  id, group_id, group_name, slug, name, short_description, description,
  preview_image_url, base_price, is_popular, is_recommended, requires_sensitive_review, sort_order, is_active, is_demo
) values
  ('20000000-0000-0000-0000-000000000001', '10000000-0000-0000-0000-000000000001', 'ป้ายตัวตนและข้อมูลร้าน', 'shop-banner', 'ป้ายร้านค้า', 'ป้ายแนะนำชื่อร้าน สโลแกน และจุดเด่นสำหรับโปรไฟล์หรือหน้าเพจ', 'ป้ายต้อนรับหน้าร้านออนไลน์ ช่วยสร้างภาพลักษณ์แบรนด์ให้น่ารัก น่าจดจำ ใช้ตั้งเป็นภาพปกหรือโพสต์ปักหมุด', '/placeholders/signs/sign-01.svg', 59.00, true, true, false, 1, true, true),
  ('20000000-0000-0000-0000-000000000002', '10000000-0000-0000-0000-000000000001', 'ป้ายตัวตนและข้อมูลร้าน', 'shop-details', 'ป้ายรายละเอียดร้าน', 'สรุปข้อมูลสินค้า บริการ และขั้นตอนการสั่งซื้อเข้าใจง่ายในภาพเดียว', 'รวบรวมรายละเอียดสำคัญของร้าน เช่น สินค้าที่จำหน่าย รอบจัดส่ง และบริการพิเศษ', '/placeholders/signs/sign-02.svg', 59.00, true, false, false, 2, true, true),
  ('20000000-0000-0000-0000-000000000003', '10000000-0000-0000-0000-000000000002', 'ป้ายการเงินและเรทราคา', 'bank-account', 'ป้ายบัญชีธนาคาร', 'ป้ายแจ้งเลขบัญชี ชื่อบัญชี และพร้อมเพย์ อ่านชัดเจน ส่งให้ลูกค้าในแชตได้ทันที', 'ออกแบบให้อ่านตัวเลขชัดเจน ลดการโอนผิด พร้อมระบบตรวจสอบความถูกต้องก่อนส่งคำสั่งซื้อ', '/placeholders/signs/sign-03.svg', 49.00, true, true, true, 3, true, true),
  ('20000000-0000-0000-0000-000000000004', '10000000-0000-0000-0000-000000000002', 'ป้ายการเงินและเรทราคา', 'payment-channels', 'ป้ายแจ้งช่องทางชำระเงิน', 'รวมทุกช่องทางชำระเงิน โอนธนาคาร พร้อมเพย์ วอลเล็ท บัตรเครดิต', 'สรุปช่องทางรับชำระเงินทั้งหมดของร้านในป้ายเดียว สะดวกต่อการแจ้งลูกค้า', '/placeholders/signs/sign-04.svg', 49.00, false, false, true, 4, true, true),
  ('20000000-0000-0000-0000-000000000005', '10000000-0000-0000-0000-000000000003', 'ป้ายรีวิวและเครดิตความน่าเชื่อถือ', 'credit-sign', 'ป้ายเครดิต', 'ป้ายกรอบเครดิตร้านค้า ป้องกันการแอบอ้างและเพิ่มความมั่นใจให้ลูกค้าใหม่', 'กรอบและป้ายแสดงเครดิตการขาย ส่งจริง รีวิวจริง เสริมความน่าเชื่อถือให้ร้านค้าออนไลน์', '/placeholders/signs/sign-05.svg', 45.00, false, false, false, 5, true, true),
  ('20000000-0000-0000-0000-000000000006', '10000000-0000-0000-0000-000000000003', 'ป้ายรีวิวและเครดิตความน่าเชื่อถือ', 'customer-review', 'ป้ายรีวิว', 'ป้ายโชว์ความประทับใจจากลูกค้า พร้อมดาวคะแนนและกรอบรูปน่ารัก', 'นำข้อความรีวิวจากลูกค้ามาจัดวางอย่างสวยงาม น่าอ่าน ช่วยกระตุ้นการตัดสินใจซื้อ', '/placeholders/signs/sign-06.svg', 39.00, true, true, false, 6, true, true),
  ('20000000-0000-0000-0000-000000000007', '10000000-0000-0000-0000-000000000001', 'ป้ายตัวตนและข้อมูลร้าน', 'open-close-hours', 'ป้ายเปิด-ปิดร้าน', 'แจ้งเวลาทำการ เวลาตอบแชต และวันหยุดประจำสัปดาห์', 'ช่วยให้ลูกค้าทราบเวลาเปิดรับออเดอร์และรอบตอบแชต ลดการรอนาน', '/placeholders/signs/sign-07.svg', 39.00, true, false, false, 7, true, true),
  ('20000000-0000-0000-0000-000000000008', '10000000-0000-0000-0000-000000000002', 'ป้ายการเงินและเรทราคา', 'price-rate', 'ป้ายเรทราคา', 'ตารางเรทราคาสินค้า แพ็กเกจ หรือเรทตัวแทนจำหน่าย อ่านง่ายสบายตา', 'จัดระเบียบรายการสินค้าและราคาให้ชัดเจน ลูกค้าเลือกแพ็กเกจได้ทันทีโดยไม่ต้องถามซ้ำ', '/placeholders/signs/sign-08.svg', 59.00, true, true, false, 8, true, true),
  ('20000000-0000-0000-0000-000000000009', '10000000-0000-0000-0000-000000000002', 'ป้ายการเงินและเรทราคา', 'promotion-banner', 'ป้ายโปรโมชั่น', 'ป้ายจัดโปรลดราคา แถมฟรี หรือแคมเปญประจำเดือนสุดคุ้ม', 'ป้ายโปรโมชั่นสะดุดตาสำหรับโพสต์ลงโซเชียลมีเดียเพื่อกระตุ้นยอดขาย', '/placeholders/signs/sign-09.svg', 59.00, false, true, false, 9, true, true),
  ('20000000-0000-0000-0000-000000000010', '10000000-0000-0000-0000-000000000003', 'ป้ายรีวิวและเครดิตความน่าเชื่อถือ', 'thank-you-card', 'ป้ายขอบคุณลูกค้า', 'ป้ายส่งคำขอบคุณหลังจบออเดอร์ หรือทำเป็นการ์ดแนบในกล่องพัสดุ', 'สร้างความประทับใจให้ลูกค้ากลับมาซื้อซ้ำด้วยข้อความขอบคุณแสนอบอุ่น', '/placeholders/signs/sign-10.svg', 39.00, false, false, false, 10, true, true),
  ('20000000-0000-0000-0000-000000000011', '10000000-0000-0000-0000-000000000004', 'ป้ายจัดส่งและแจ้งข่าวสาร', 'tracking-number', 'ป้ายแจ้งเลขพัสดุ', 'ป้ายแจ้งรอบส่งและเลขพัสดุประจำวัน พร้อมโลโก้ขนส่ง', 'เทมเพลตแจ้งเลขพัสดุและรอบจัดส่ง ดูเป็นมืออาชีพและใส่ใจทุกออเดอร์', '/placeholders/signs/sign-11.svg', 45.00, false, false, false, 11, true, true),
  ('20000000-0000-0000-0000-000000000012', '10000000-0000-0000-0000-000000000004', 'ป้ายจัดส่งและแจ้งข่าวสาร', 'contact-channels', 'ป้ายช่องทางติดต่อ', 'รวม LINE, IG, Facebook, TikTok และเบอร์โทรไว้ในภาพเดียว', 'ให้ลูกค้าติดตามและทักหาได้ทุกช่องทางโซเชียลมีเดียอย่างครบถ้วน', '/placeholders/signs/sign-12.svg', 45.00, false, false, false, 12, true, true),
  ('20000000-0000-0000-0000-000000000013', '10000000-0000-0000-0000-000000000004', 'ป้ายจัดส่งและแจ้งข่าวสาร', 'holiday-notice', 'ป้ายแจ้งวันหยุด', 'ป้ายประกาศหยุดร้านชั่วคราว วันหยุดเทศกาล และวันเปิดทำการปกติ', 'แจ้งกำหนดการปิดร้านและรอบจัดส่งถัดไปอย่างสุภาพและชัดเจน', '/placeholders/signs/sign-13.svg', 39.00, false, false, false, 13, true, true),
  ('20000000-0000-0000-0000-000000000014', '10000000-0000-0000-0000-000000000001', 'ป้ายตัวตนและข้อมูลร้าน', 'shop-rules', 'ป้ายกฎและเงื่อนไขร้าน', 'ป้ายแจ้งเงื่อนไขการสั่งซื้อ การเคลมสินค้า และการมัดจำ', 'ลดปัญหาข้อพิพาทด้วยการแจ้งเงื่อนไขร้านค้าและการรับประกันที่เข้าใจง่าย', '/placeholders/signs/sign-14.svg', 49.00, false, false, false, 14, true, true),
  ('20000000-0000-0000-0000-000000000015', '10000000-0000-0000-0000-000000000004', 'ป้ายจัดส่งและแจ้งข่าวสาร', 'custom-other-sign', 'ป้ายประกาศและป้ายอื่น ๆ', 'ป้ายรูปแบบพิเศษตามความต้องการของร้าน (แอดมินเพิ่มประเภทป้ายได้ไม่จำกัด)', 'รองรับป้ายประกาศเฉพาะกิจ ป้ายรับสมัครตัวแทน หรือป้ายข้อความพิเศษ', '/placeholders/signs/sign-15.svg', 59.00, false, false, false, 15, true, true)
on conflict (slug) do update
