-- 8. Dynamic Form Fields per Sign Category (PART 10)
insert into public.product_fields (
  sign_category_id, field_key, label, placeholder, field_type, options, is_required, help_text, is_sensitive, sort_order, is_active, is_demo
) values
  -- 1. ป้ายร้านค้า
  ('20000000-0000-0000-0000-000000000001', 'shop_name', 'ชื่อร้าน', 'เช่น Bunny Pastel Shop', 'text', '[]'::jsonb, true, 'ชื่อร้านหลักที่ต้องการให้เด่นที่สุดบนป้าย', false, 1, true, true),
  ('20000000-0000-0000-0000-000000000001', 'tagline', 'คำโปรย / สโลแกนร้าน', 'เช่น เสื้อผ้าแฟชั่นพาสเทล พร้อมส่งทุกวัน', 'text', '[]'::jsonb, true, 'ข้อความสั้น ๆ แนะนำจุดเด่นของร้าน', false, 2, true, true),
  ('20000000-0000-0000-0000-000000000001', 'extra_text', 'ข้อความเพิ่มเติม', 'เช่น ส่งฟรีเมื่อช้อปครบ 500.- / รับตัวแทนจำหน่าย', 'textarea', '[]'::jsonb, false, 'ข้อมูลเสริมที่ต้องการใส่ในป้าย (ถ้ามี)', false, 3, true, true),
  ('20000000-0000-0000-0000-000000000001', 'reference_image', 'อัปโหลดโลโก้ร้านหรือภาพประกอบ (ถ้ามี)', '', 'image_upload', '[]'::jsonb, false, 'รองรับไฟล์ PNG, JPG, WEBP ขนาดไม่เกิน 5 MB', false, 4, true, true),

  -- 2. ป้ายรายละเอียดร้าน
  ('20000000-0000-0000-0000-000000000002', 'shop_name', 'ชื่อร้าน', 'เช่น Sweetie Bakery', 'text', '[]'::jsonb, true, '', false, 1, true, true),
  ('20000000-0000-0000-0000-000000000002', 'service_details', 'รายละเอียดสินค้าและบริการ', 'ระบุรายการสินค้า จุดเด่น หรือขั้นตอนสั่งซื้อ', 'textarea', '[]'::jsonb, true, '', false, 2, true, true),
