    'content',
    '[
      {"step": 1, "title": "เลือกประเภทป้ายและสไตล์", "description": "เลือกป้ายที่ต้องการ เช่น ป้ายร้านค้า ป้ายบัญชี ป้ายเรทราคา พร้อมเลือกสไตล์ Minimal หรือ Decorative"},
      {"step": 2, "title": "เลือกเทมเพลตและของตกแต่งฟรี", "description": "เลือกภาพเทมเพลตสำเร็จรูป และเลือกของตกแต่งพาสเทล (โบว์ ดอกไม้ หัวใจ ดาว) ฟรี 0 บาททุกชิ้น"},
      {"step": 3, "title": "กรอกข้อความที่ต้องการใส่ในป้าย", "description": "กรอกข้อมูลตามประเภทป้าย พร้อมตรวจทานความถูกต้องและราคาที่โปร่งใสก่อนยืนยัน"},
      {"step": 4, "title": "ยืนยันออเดอร์และรอรับไฟล์งานสวย ๆ", "description": "รับหมายเลขออเดอร์สำหรับติดตามสถานะการออกแบบจนส่งมอบงาน"}
